import { create } from 'zustand';
import { guessLang, isLang, isRtl, type LangCode } from '@es/shared';

/**
 * Interface text translation, gettext style: the English string is the key (`t('Send')`,
 * `t('Waiting for {name}…', { name })`). Catalogs live in ./locales/<code>.json and are generated by
 * `pnpm --filter @es/api i18n:translate` (Claude). Missing keys fall back to English.
 *
 * Two settings:
 *  - lang: the learner's own language. Every learning translation (meanings, subtitles, explanations,
 *    the translate button) uses it. 'en' = no translation.
 *  - ui: 'auto' = interface in `lang` when a catalog exists; 'en' = keep the interface in English for practice.
 */
const loaders = import.meta.glob<Record<string, string>>('./locales/*.json', { import: 'default' });
const loaderFor = (code: string) => loaders[`./locales/${code}.json`];

const LS_LANG = 'es:lang';
const LS_UI = 'es:uiLang';

function initialLang(): { lang: LangCode; chosen: boolean } {
  const saved = localStorage.getItem(LS_LANG);
  if (isLang(saved)) return { lang: saved, chosen: true };
  return { lang: guessLang(typeof navigator === 'undefined' ? [] : navigator.languages ?? [navigator.language]), chosen: false };
}

interface LangState {
  lang: LangCode;
  /** The learner picked it (or it came from their profile); otherwise it was guessed from the browser. */
  chosen: boolean;
  ui: 'auto' | 'en';
  /** Language the interface is shown in right now (catalog loaded). */
  uiLang: LangCode;
  catalog: Record<string, string>;
  setLang: (lang: LangCode, opts?: { fromProfile?: boolean }) => void;
  setUi: (ui: 'auto' | 'en') => void;
}

const first = initialLang();
/** Page / app description (also the PWA manifest description, see vite.config.ts). */
const APP_DESCRIPTION = tk('Practise real-life English on a 3D street with AI shopkeepers and other learners.');

export const useLang = create<LangState>((set, get) => ({
  lang: first.lang,
  chosen: first.chosen,
  ui: localStorage.getItem(LS_UI) === 'en' ? 'en' : 'auto',
  uiLang: 'en',
  catalog: {},
  setLang(lang, opts) {
    localStorage.setItem(LS_LANG, lang);
    set({ lang, chosen: true });
    void applyUi();
    if (!opts?.fromProfile) for (const fn of listeners) fn(lang);
  },
  setUi(ui) {
    localStorage.setItem(LS_UI, ui);
    set({ ui });
    void applyUi();
  },
}));

const listeners = new Set<(lang: LangCode) => void>();
/** Called when the learner changes their language (profile sync, analytics). */
export function onLangChange(fn: (lang: LangCode) => void) {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

let loadSeq = 0;
async function applyUi() {
  const { lang, ui } = useLang.getState();
  const want: LangCode = ui === 'en' ? 'en' : lang;
  const seq = ++loadSeq;
  let catalog: Record<string, string> = {};
  let shown: LangCode = 'en';
  const loader = want === 'en' ? undefined : loaderFor(want);
  if (loader) {
    try {
      catalog = await loader();
      shown = want;
    } catch {
      /* offline and not cached: stay in English */
    }
  }
  if (seq !== loadSeq) return;
  useLang.setState({ catalog, uiLang: shown });
  const html = document.documentElement;
  html.lang = shown;
  html.dir = isRtl(shown) ? 'rtl' : 'ltr';
  // page description and the installable app's manifest in the same language (manifest-<code>.webmanifest: vite.config.ts)
  document.querySelector('meta[name="description"]')?.setAttribute('content', catalog[APP_DESCRIPTION] || APP_DESCRIPTION);
  const link = document.querySelector('link[rel="manifest"]');
  if (link) link.setAttribute('href', shown === 'en' ? '/manifest.webmanifest' : `/manifest-${shown}.webmanifest`);
}
void applyUi();

export type Vars = Record<string, string | number>;

/** Translate an interface string (non-reactive; components should use `useT()`). */
export function t(key: string, vars?: Vars): string {
  const s = useLang.getState().catalog[key] || key;
  return vars ? s.replace(/\{(\w+)\}/g, (m, k: string) => (k in vars ? String(vars[k]) : m)) : s;
}

/** Marks a string as an interface key without translating it yet (module-level tables); translate later with t(). */
export function tk(s: string): string {
  return s;
}

/** `const t = useT()` — re-renders the component when the interface language changes. */
export function useT(): typeof t {
  useLang((s) => s.catalog);
  return t;
}

/** The learner's own language (for API calls that translate or explain). */
export function learnerLang(): LangCode {
  return useLang.getState().lang;
}
